proc routeConfinedPmtestModule[T](instance: T, bare: string, params: ptr UncheckedArray[uint8], len: int, inv: Invocation): Future[Result[seq[byte], InvocationFailure]] {.async: (raises: []).} =
  mixin `handoff`, `inspect`, `install`, `remove`, `resolve`, `status`, `update`
  var request = kitValidator().checkedRequestAt(bare, params, len)
  if request.isErr:
    return Result[seq[byte], InvocationFailure].err(request.unsafeError)
  if bare == "handoff":
    var typed = fromChecked(PmtestHandoffRequest, request.unsafeGet)
    var response: Result[PmtestHandoffResponse, InvocationFailure]
    when compiles(`handoff`(instance, typed, inv)):
      settleHandler(response, `handoff`(instance, typed, inv), inv)
    else:
      let saved = enterPlain(inv)
      response = `handoff`(instance, typed)
      leavePlain(saved)
